/**
 * data-loader.js — loads cv data and normalizes it once.
 * Data is split in TWO files: cv_data.json (textual content) + cv_ui.json
 * (non-textual: theme, colors, particles, glass material). They are fetched
 * FIRST (no-store) so editing either JSON + refresh shows changes immediately
 * over http, and merged into one object. Falls back to window.CV_DATA /
 * window.CV_UI (generated by tools/sync-data.mjs) when fetch fails or is !ok —
 * which covers the file:// case where fetch is blocked.
 */
import {
  buildTagDomainMap,
  buildUnits
} from "./filter-engine.js";

let normalized = null;

function normalize(raw) {
  const taxonomy = raw.tag_taxonomy;
  const tagDomain = buildTagDomainMap(taxonomy);

  // Each experience references its expskills explicitly; keep only valid ids.
  for (const exp of raw.experience) {
    exp._tags = [...new Set(exp.expskills || [])].filter((id) => tagDomain.has(id));
    exp._domains = [...new Set(exp._tags.map((t) => tagDomain.get(t)))];
  }
  const units = buildUnits(raw, taxonomy);
  // Index units back onto experiences/projects for the renderer
  const byExp = new Map();
  for (const unit of units) {
    if (!byExp.has(unit.expId)) byExp.set(unit.expId, []);
    byExp.get(unit.expId).push(unit);
  }
  for (const exp of raw.experience) exp._units = byExp.get(exp.id) || [];

  return { ...raw, _tagDomain: tagDomain, _units: units };
}

async function fetchJSON(url) {
  try {
    const res = await fetch(url, { cache: "no-store" });
    if (res.ok) return await res.json();
  } catch {
    /* file:// or network error — caller falls back to the inlined snapshot */
  }
  return null;
}

/** Load + normalize (idempotent). Merges cv_data.json + cv_ui.json. */
export async function loadData() {
  if (normalized) return normalized;
  const [content, ui] = await Promise.all([
    fetchJSON("cv_data.json"),
    fetchJSON("cv_ui.json")
  ]);
  const cvData = content || window.CV_DATA;
  const cvUi = ui || window.CV_UI || {};
  if (!cvData) throw new Error("Failed to load cv_data.json and no window.CV_DATA fallback");
  // cv_ui.json contributes the non-textual keys (site_config, domain_colors,
  // glass); cv_data.json keeps textual content. Merge into one raw object.
  const raw = { ...cvData, ...cvUi };
  normalized = normalize(raw);
  return normalized;
}

/** Synchronous access after loadData() resolved. */
export function getData() {
  if (!normalized) throw new Error("getData() called before loadData() resolved");
  return normalized;
}
